-- m178: بازنویسی محاوره‌ای توضیح ابزارها (فرم خانواده/معلم + فرم‌های درمانگر) — لحن دوستانه و ساده
-- ثابت: کلیدها، فیلدها، نمره‌دهی، باندها — فقط description؛ حذف نشت واژگان فنی از شرح‌حال و odd
UPDATE case_event_types SET description = 'فرم گفت‌وگوی اول با خانواده — هفت بخش آشنا: مشکل به زبان شما، بارداری و تولد، رشد، سلامت، خانه و خانواده، مدرسه، و نقاط قوت کودک. نگرانی‌های خواندن/نوشتن/ریاضی، توجه و بی‌قراری، اضطراب امتحان و مسائل مدرسه گزینه‌ای ثبت می‌شن تا سامانه بتونه ازشون مستقیم مسیر ارزیابی بسازه. حدود ۲۰ دقیقه وقت می‌بره. نسخهٔ ۲ فقط برای پرونده‌های قدیمی بازه.', updated_at = '2026-10-23T00:00:00.000Z' WHERE key = 'ce-anamnesis-v3' AND deleted_at IS NULL;
UPDATE case_event_types SET description = 'شانزده جمله دربارهٔ ارتباط، بازی و رفتارهای تکراری — از تماس چشمی و واکنش دوطرفه تا چسبیدن به روتین و واکنش به صدا و نور. این فرم به‌تنهایی تشخیص نمی‌ده؛ پرچم ارجاع تخصصی همیشه فعاله.', updated_at = '2026-10-23T00:00:00.000Z' WHERE key = 'ce-asd-criteria-v1' AND deleted_at IS NULL;
UPDATE case_event_types SET description = 'بعد از دیدن نتیجهٔ چک‌لیست‌های والد و معلم، شک فعلی، خلاصهٔ نتایج و تصمیم قدم بعد رو این‌جا ثبت کنید. این جمع‌بندی می‌ره توی تایم‌لاین پرونده و گزارش کمیسیون.', updated_at = '2026-10-23T00:00:00.000Z' WHERE key = 'ce-clinical-suspicion-v1' AND deleted_at IS NULL;
UPDATE case_event_types SET description = 'یک لینک برای خانواده؛ پنج بخش پشت سر هم: چند پرسش کوتاه زمینه، چک‌لیست توجه و بی‌قراری (SNAP-IV)، پرسش‌نامهٔ رفتار (SDQ)، پرسش‌نامهٔ اضطراب (SCARED) و سنجهٔ انطباق روزمره. هر بخش جدا نمره می‌خوره و روی پرونده می‌شینه. حدود ۲۵ تا ۳۵ دقیقه وقت می‌بره؛ با آرامش جلو برید — همهٔ جواب‌ها یک‌جا آخرش ارسال می‌شه.', updated_at = '2026-10-23T00:00:00.000Z' WHERE key = 'ce-comp-family-v2' AND deleted_at IS NULL;
UPDATE case_event_types SET description = 'برای هر معلم یک لینک جداگانه؛ چهار بخش پشت سر هم: چند پرسش کوتاه از مشاهدهٔ کلاس، چک‌لیست توجه و بی‌قراری (SNAP-IV)، پرسش‌نامهٔ رفتار (SDQ) و ملاک‌های کلاسی خواندن/نوشتن/حساب. هر بخش جدا نمره می‌خوره و با نام خود معلم روی پروندهٔ دانش‌آموز می‌شینه. حدود ۱۵ تا ۲۰ دقیقه وقت می‌بره؛ با آرامش جلو برید — همهٔ جواب‌ها یک‌جا آخرش ارسال می‌شه.', updated_at = '2026-10-23T00:00:00.000Z' WHERE key = 'ce-comp-teacher-v2' AND deleted_at IS NULL;
UPDATE case_event_types SET description = 'پانزده جمله دربارهٔ مهارت‌های حرکتی فرزندتان — از پرتاب توپ و پله رفتن تا دست‌خط و کار با قیچی. فقط بگید هر جمله چقدر شبیه خودشه؛ جواب درست و غلط نداره. حدود ۱۰ دقیقه وقت می‌بره.', updated_at = '2026-10-23T00:00:00.000Z' WHERE key = 'ce-dcdq-v1' AND deleted_at IS NULL;
