UPDATE case_event_types SET description = 'با تکیه بر شواهد، نوع نیاز ویژه و پروتکل مداخلهٔ اصلی (و اگه لازم شد پروتکل پشتیبان) رو نهایی کنید؛ هدف‌های کوچک دورهٔ اول و برنامهٔ جلسات هم همین‌جا ثبت می‌شه.', updated_at = '2026-10-23T00:00:00.000Z' WHERE key = 'ce-needs-v1' AND deleted_at IS NULL;
