UPDATE case_event_types SET description = 'دو دقیقه حساب سریع + ده جفت مقایسهٔ عدد + جاگذاری روی خط عدد. نتیجه خودکار با انتظار پایه مقایسه می‌شه.', updated_at = '2026-10-23T00:00:00.000Z' WHERE key = 'ce-probe-calc-v1' AND deleted_at IS NULL;
